fn main(input: Dir) -> Result<Str, IoErr> {
  let b = input.read("text.txt")?;
  let n = b.len();
  let mut counts: Map<Str, Int> = Map::new();
  let mut start = -1;
  let mut i = 0;
  while i <= n {
    let mut letter = false;
    if i < n {
      let c = b[i];
      letter = (c >= 65 && c <= 90) || (c >= 97 && c <= 122);
    }
    if letter {
      if start < 0 {
        start = i;
      }
    } else if start >= 0 {
      let w = b.slice(start, i).to_str().to_lowercase();
      counts.insert(w, counts.get(w).unwrap_or(0) + 1);
      start = -1;
    }
    i += 1;
  }
  let mut keys = counts.keys();
  keys.sort_by(|a, b| {
    let ca = counts.get(a).unwrap_or(0);
    let cb = counts.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  let mut out = "";
  let mut idx = 0;
  for k in keys {
    if idx >= 5 {
      break;
    }
    out = out + k + " " + counts.get(k).unwrap_or(0).to_str() + "\n";
    idx += 1;
  }
  Ok(out)
}

struct Tot { region: Str, qty: Int, rev: Int }

fn money(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { 0 - c } else { c };
  let cents = a % 100;
  let mut cs = cents.to_str();
  if cents < 10 { cs = "0" + cs; }
  let s = (a / 100).to_str() + "." + cs;
  if neg { "-" + s } else { s }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut qty: Map<Str, Int> = Map::new();
  let mut rev: Map<Str, Int> = Map::new();
  let mut skipped = 0;
  let mut first = true;
  for line in text.lines() {
    if first { first = false; continue; }
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 5 { skipped += 1; continue; }
    let Some(q) = parts[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(u) = parts[4].trim().parse_int() else { skipped += 1; continue; };
    let region = parts[1].trim();
    qty.insert(region, qty.get(region).unwrap_or(0) + q);
    rev.insert(region, rev.get(region).unwrap_or(0) + q * u);
  }
  let mut rows: List<Tot> = [];
  for r in rev.keys() {
    rows.push(Tot { region: r, qty: qty.get(r).unwrap_or(0), rev: rev.get(r).unwrap_or(0) });
  }
  rows.sort_by(|a, b| a.rev > b.rev || (a.rev == b.rev && a.region < b.region));
  let mut out = "";
  for t in rows {
    out = out + t.region + " " + t.qty.to_str() + " " + money(t.rev) + "\n";
  }
  out = out + "skipped " + skipped.to_str() + "\n";
  Ok(out)
}

struct Entry { ip: Str, status: Int, size: Int, path: Str }
struct ErrCount { ip: Str, n: Int }

fn parse_line(line: Str) -> Option<Entry> {
  let sp = line.find(" ")?;
  if sp == 0 { return None; }
  let ip = line.slice(0, sp);
  let q1 = line.find("\"")?;
  if q1 < sp { return None; }
  let rest = line.slice(q1 + 1, line.len());
  let q2 = rest.find("\"")?;
  let req = rest.slice(0, q2).split(" ");
  if req.len() != 3 { return None; }
  let after = rest.slice(q2 + 1, rest.len()).trim().split(" ");
  if after.len() != 2 { return None; }
  let status = after[0].parse_int()?;
  let size = if after[1] == "-" { 0 } else { after[1].parse_int()? };
  let p = req[1];
  let path = match p.find("?") {
    Some(i) => p.slice(0, i),
    None => p,
  };
  Some(Entry { ip: ip, status: status, size: size, path: path })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse_line(line) else { continue; };
    statuses.insert(e.status, statuses.get(e.status).unwrap_or(0) + 1);
    total = total + e.size;
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    if e.status >= 500 && e.status <= 599 {
      errs.insert(e.ip, errs.get(e.ip).unwrap_or(0) + 1);
    }
  }
  let mut out: List<Str> = [];
  for k in statuses.keys() {
    out.push(k.to_str() + " " + statuses.get(k).unwrap_or(0).to_str());
  }
  out.push("bytes " + total.to_str());
  let mut best = "";
  let mut best_n = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > best_n {
      best = p;
      best_n = n;
    }
  }
  if best_n > 0 {
    out.push("top " + best + " " + best_n.to_str());
  }
  let mut list: List<ErrCount> = [];
  for ip in errs.keys() {
    list.push(ErrCount { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  list.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for e in list {
    out.push("errors " + e.ip + " " + e.n.to_str());
  }
  Ok(out.join("\n"))
}

fn order_total(o: Json) -> Int {
  let mut t = 0;
  let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);
  for it in items {
    let q = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
    let p = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
    t = t + q * p;
  }
  t
}

fn main(input: Dir) -> Result<Str, Str> {
  let bytes = match input.read("orders.json") {
    Ok(b) => b,
    Err(_) => return Err("cannot read orders.json"),
  };
  let doc = match bytes.to_str().parse_json() {
    Ok(j) => j,
    Err(e) => return Err(e),
  };
  let orders = match doc.as_list() {
    Some(l) => l,
    None => return Err("orders.json is not an array"),
  };

  let mut counts: Map<Str, Int> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut ref_n = 0;
  let mut ref_total = 0;
  let mut pend_n = 0;

  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    let customer = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
    let total = order_total(o);
    match status {
      "paid" => {
        counts.insert(customer, counts.get(customer).unwrap_or(0) + 1);
        totals.insert(customer, totals.get(customer).unwrap_or(0) + total);
      }
      "refunded" => {
        ref_n = ref_n + 1;
        ref_total = ref_total + total;
      }
      "pending" => {
        pend_n = pend_n + 1;
      }
      _ => {}
    }
  }

  let mut out = "";
  for c in counts.keys() {
    out = out + c + " " + counts.get(c).unwrap_or(0).to_str() + " " + totals.get(c).unwrap_or(0).to_str() + "\n";
  }
  out = out + "refunded " + ref_n.to_str() + " " + ref_total.to_str() + "\n";
  out = out + "pending " + pend_n.to_str() + "\n";
  Ok(out)
}

fn norm(line: Str) -> Option<Str> {
  let s = line.trim().to_lowercase();
  let parts = s.split("@");
  if parts.len() != 2 { return None; }
  let local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !domain.contains(".") || domain.starts_with(".") || domain.ends_with(".") {
    return None;
  }
  if domain == "gmail.com" {
    let mut l = local;
    if let Some(i) = l.find("+") {
      l = l.slice(0, i);
    }
    l = l.replace(".", "");
    return Some(l + "@" + domain);
  }
  Some(s)
}

