}

fn to_roman(n: Int) -> Str {
  let vals: List<Int> = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms: List<Str> = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut r = "";
  let mut m = n;
  let mut i = 0;
  while i < vals.len() {
    while m >= vals[i] {
      r = r + syms[i];
      m -= vals[i];
    }
    i += 1;
  }
  r
}

fn sym_val(c: Str) -> Int {
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0,
  }
}

fn from_roman(s: Str) -> Option<Int> {
  let n = s.len();
  if n == 0 { return None; }
  let mut total = 0;
  let mut i = 0;
  while i < n {
    let v = sym_val(s.slice(i, i + 1));
    if v == 0 { return None; }
    let next = if i + 1 < n { sym_val(s.slice(i + 1, i + 2)) } else { 0 };
    if next > v { total -= v; } else { total += v; }
    i += 1;
  }
  if total < 1 || total > 3999 { return None; }
  if to_roman(total) == s { Some(total) } else { None }
}

fn convert(t: Str) -> Str {
  match t.parse_int() {
    Some(n) => {
      if t.starts_with("+") || n < 1 || n > 3999 { "invalid" } else { to_roman(n) }
    },
    None => {
      match from_roman(t) {
        Some(v) => v.to_str(),
        None => "invalid",
      }
    },
  }
}

