fn closer_str(c: Int) -> Str {
  match c {
    41 => ")",
    93 => "]",
    _ => "}",
  }
}

fn check(line: Str) -> Str {
  let b = line.to_bytes();
  let mut stack: List<Int> = [];
  let mut i = 0;
  while i < b.len() {
    let c = b[i];
    if c == 40 {
      stack.push(41);
    } else if c == 91 {
      stack.push(93);
    } else if c == 123 {
      stack.push(125);
    } else if c == 41 || c == 93 || c == 125 {
      let Some(x) = stack.pop() else {
        return "col " + (i + 1).to_str() + ": unexpected " + closer_str(c);
      };
      if x != c {
        return "col " + (i + 1).to_str() + ": expected " + closer_str(x) + ", found " + closer_str(c);
      }
    }
    i += 1;
  }
  if stack.len() == 0 {
    "ok"
  } else {
    "unclosed " + closer_str(stack[stack.len() - 1])
  }
}

