fn pct(t: List<Int>, p: Int) -> Int {
  let n = t.len();
  let k = (p * n + 99) / 100;
  t[k - 1]
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut groups: Map<Str, List<Int>> = Map::new();
  for line in text.lines() {
    let parts = line.split(" ");
    if parts.len() != 3 { continue; }
    let Some(ms) = parts[2].parse_int() else { continue; };
    let key = parts[0] + " " + parts[1];
    let mut cur: List<Int> = groups.get(key).unwrap_or([]);
    cur.push(ms);
    groups.insert(key, cur);
  }
  let mut out = "";
  for key in groups.keys() {
    let mut t: List<Int> = groups.get(key).unwrap_or([]);
    if t.len() == 0 { continue; }
    t.sort();
    out = out + key + " count=" + t.len().to_str()
      + " p50=" + pct(t, 50).to_str()
      + " p95=" + pct(t, 95).to_str()
      + " max=" + t[t.len() - 1].to_str() + "\n";
  }
  Ok(out)
}

struct Edge { to: Str, cost: Int }
struct Trip { from: Str, to: Str }

fn dijkstra(adj: Map<Str, List<Edge>>, src: Str) -> Map<Str, Int> {
  let mut dist: Map<Str, Int> = Map::new();
  dist.insert(src, 0);
  let mut done: Map<Str, Bool> = Map::new();
  loop {
    let mut best: Option<Str> = None;
    let mut bd = 0;
    for k in dist.keys() {
      if done.get(k).is_none() {
        let d = dist.get(k).unwrap_or(0);
        if best.is_none() || d < bd {
          best = Some(k);
          bd = d;
        }
      }
    }
    let Some(u) = best else { break; };
    done.insert(u, true);
    let edges: List<Edge> = adj.get(u).unwrap_or([]);
    for e in edges {
      let nd = bd + e.cost;
      let cur = dist.get(e.to);
      if cur.is_none() || nd < cur.unwrap_or(0) {
        dist.insert(e.to, nd);
      }
    }
  }
  dist
}

fn route(adj: Map<Str, List<Edge>>, t: Trip) -> Str {
  let dist = dijkstra(adj, t.to);
  let Some(total) = dist.get(t.from) else {
    return t.from + " " + t.to + " unreachable";
  };
  let mut names: List<Str> = [t.from];
  let mut cur = t.from;
  let mut dcur = total;
  while cur != t.to {
    let mut best: Option<Str> = None;
    let mut bdv = 0;
    let edges: List<Edge> = adj.get(cur).unwrap_or([]);
    for e in edges {
      if let Some(dv) = dist.get(e.to) {
        if e.cost + dv == dcur {
          if best.is_none() || e.to < best.unwrap_or("") {
            best = Some(e.to);
            bdv = dv;
          }
        }
      }
    }
    let Some(nx) = best else { break; };
    names.push(nx);
    cur = nx;
    dcur = bdv;
  }
  names.join(" -> ") + " " + total.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut adj: Map<Str, List<Edge>> = Map::new();
  let mut trips: List<Trip> = [];
  for raw in text.lines() {
    let line = raw.replace("\t", " ").trim();
    if line.len() == 0 || line.starts_with("#") { continue; }
    let parts = line.split(" ").filter(|p| p.len() > 0);
    if parts.len() == 4 && parts[0] == "road" {
      let Some(c) = parts[3].parse_int() else { continue; };
      if c <= 0 { continue; }
      let a = parts[1];
      let b = parts[2];
      let mut la: List<Edge> = adj.get(a).unwrap_or([]);
      la.push(Edge { to: b, cost: c });
      adj.insert(a, la);
      let mut lb: List<Edge> = adj.get(b).unwrap_or([]);
      lb.push(Edge { to: a, cost: c });
      adj.insert(b, lb);
    } else if parts.len() == 3 && parts[0] == "trip" {
      trips.push(Trip { from: parts[1], to: parts[2] });
    }
  }
  let mut out: List<Str> = [];
  for t in trips {
    out.push(route(adj, t));
  }
  Ok(out.join("\n"))
}

struct Entry { path: Str, line: Str }

fn merge(base: Json, over: Json) -> Json {
  let Json::Obj(om) = over else { return over; };
  let mut r: Map<Str, Json> = Map::new();
  if let Json::Obj(bm) = base { r = bm; }
  for k in om.keys() {
    let v = om.get(k).unwrap_or(Json::Null);
    match v {
      Json::Null => { r.remove(k); }
      Json::Obj(_) => {
        let b = r.get(k).unwrap_or(Json::Null);
        r.insert(k, merge(b, v));
      }
      _ => { r.insert(k, v); }
    }
  }
  Json::Obj(r)
}

fn flatten(path: Str, j: Json, acc: List<Entry>) -> List<Entry> {
  let mut out = acc;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.push(Entry { path: path, line: path + "={}" });
      } else {
        for k in m.keys() {
          let child = if path == "" { k } else { path + "." + k };
          out = flatten(child, m.get(k).unwrap_or(Json::Null), out);
        }
      }
    }
    Json::Arr(l) => {
      if l.len() == 0 {
        out.push(Entry { path: path, line: path + "=[]" });
      } else {
        for i in 0..l.len() {
          let child = if path == "" { i.to_str() } else { path + "." + i.to_str() };
          out = flatten(child, l[i], out);
        }
      }
    }
    _ => {
      out.push(Entry { path: path, line: path + "=" + j.to_json() });
    }
  }
  out
}

fn main(input: Dir) -> Result<Str, Str> {
  let bt = input.read("base.json").map_err(|e| "cannot read base.json")?;
  let ot = input.read("override.json").map_err(|e| "cannot read override.json")?;
  let base = bt.to_str().parse_json()?;
  let over = ot.to_str().parse_json()?;
  let merged = merge(base, over);
  let mut entries: List<Entry> = [];
  entries = flatten("", merged, entries);
  entries.sort_by_key(|e| e.path);
  let lines = entries.map(|e| e.line);
  Ok(lines.join("\n"))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut e = "";
  let mut w = "";
  let mut i = "";
  let mut ne = 0;
  let mut nw = 0;
  let mut ni = 0;
  let mut other = 0;
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    let parts = line.split(" ");
    if parts.len() < 3 {
      other += 1;
      continue;
    }
    let lv = parts[1].to_uppercase();
    if lv == "ERROR" {
      e = e + line + "\n";
      ne += 1;
    } else if lv == "WARN" || lv == "WARNING" {
      w = w + line + "\n";
      nw += 1;
    } else if lv == "INFO" {
      i = i + line + "\n";
      ni += 1;
    } else {
      other += 1;
    }
  }
  out.write("error.log", e.to_bytes())?;
  out.write("warn.log", w.to_bytes())?;
  out.write("info.log", i.to_bytes())?;
  Ok("error " + ne.to_str() + "\nwarn " + nw.to_str() + "\ninfo " + ni.to_str() + "\nother " + other.to_str())
}

struct Entry { path: Str, bytes: Int, lines: Int }

fn join(dir: Str, name: Str) -> Str {
  if dir == "" { name } else { dir + "/" + name }
}

fn count_lines(b: Bytes) -> Int {
  let n = b.len();
  let mut c = 0;
  for i in 0..n {
    if b[i] == 10 { c += 1; }
  }
  if n > 0 && b[n - 1] != 10 { c += 1; }
  c
}

fn walk(d: Dir, dir: Str, acc: List<Entry>) -> Result<List<Entry>, IoErr> {
  let mut res = acc;
  let names = d.list(dir)?;
  for name in names {
    if let Some(sub) = name.strip_suffix("/") {
      res = walk(d, join(dir, sub), res)?;
    } else {
      let p = join(dir, name);
      let b = d.read(p)?;
      res.push(Entry { path: p, bytes: b.len(), lines: count_lines(b) });
    }
  }
  Ok(res)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let start: List<Entry> = [];
  let mut entries = walk(input, "", start)?;
  entries.sort_by_key(|e| e.path);
  let mut text = "path,bytes,lines\n";
  let mut total = 0;
  for e in entries {
    text = text + e.path + "," + e.bytes.to_str() + "," + e.lines.to_str() + "\n";
    total += e.bytes;
  }
  out.create("index.csv", text.to_bytes())?;
  Ok("files " + entries.len().to_str() + " bytes " + total.to_str())
}

fn parse_line(line: Str) -> List<Str> {
  let b = line.to_bytes();
  let n = b.len();
  let mut fields: List<Str> = [];
  let mut cur = "".to_bytes();
  let mut in_q = false;
  let mut i = 0;
  while i < n {
    let c = b[i];
    if in_q {
      if c == 34 {
        if i + 1 < n && b[i + 1] == 34 {
          cur.push(34);
          i += 1;
        } else {
          in_q = false;
        }
      } else {
        cur.push(c);
      }
    } else if c == 34 {
      in_q = true;
    } else if c == 44 {
      fields.push(cur.to_str());
      cur = "".to_bytes();
    } else {
      cur.push(c);
    }
    i += 1;
  }
  fields.push(cur.to_str());
  fields
}

fn is_active(s: Str) -> Bool {
